import os
root = "."
skip = {".next", "node_modules", "dist", ".git", ".turbo"}
hits = []
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in skip and not d.startswith(".")]
    for fn in filenames:
        path = os.path.join(dirpath, fn)
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                text = f.read()
        except Exception:
            continue
        # exact token: issue.created not followed by identifier char
        i = 0
        found = False
        needle = "issue.created"
        while True:
            j = text.find(needle, i)
            if j < 0:
                break
            end = j + len(needle)
            nxt = text[end:end+1]
            if nxt == "" or not (nxt.isalnum() or nxt == "_"):
                found = True
                break
            i = end
        if found:
            hits.append(path[2:] if path.startswith("./") else path)
for h in sorted(hits):
    print(h)
'
